impl VideoRenderProgramError {
    /// 🔤️ The fixture's error code for this refusal.
    pub fn code(&self) -> &'static str {
        match self {
            Self::Schema { .. } => "schema",
            Self::Dimensions { .. } => "dimensions",
            Self::FrameRate { .. } => "frameRate",
